package com.atlasiq.twin;
import com.atlasiq.persistence.*;import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class ArchitectureHotspotService {private final AnalysisStore store;public ArchitectureHotspotService(AnalysisStore s){store=s;}public List<Hotspot> analyze(String id){QirModel m=store.find(id).orElseThrow().model();Map<String,Integer>degree=new HashMap<>();m.edges().forEach(e->{degree.merge(e.from(),1,Integer::sum);degree.merge(e.to(),1,Integer::sum);});Map<String,Long>findings=m.findings().stream().collect(java.util.stream.Collectors.groupingBy(f->f.resourceId(),java.util.stream.Collectors.counting()));return m.nodes().stream().filter(n->!"repository".equals(n.type())).map(n->{int d=degree.getOrDefault(n.id(),0);long f=findings.getOrDefault(n.id(),0L);int score=Math.min(100,d*5+(int)f*12);return new Hotspot(n.id(),n.name(),d,f,score);}).filter(x->x.score()>0).sorted(Comparator.comparingInt(Hotspot::score).reversed()).limit(30).toList();}public record Hotspot(String nodeId,String name,int graphDegree,long findings,int score){}}
